CREATE OR REPLACE VIEW HYBRID_ARCHIVAL_ANALYSIS AS WITH access_stats AS (SELECT s.READING_ID, s.DATA_SIZE, s.LAST_ACCESSED, TRUNC(SYSDATE - CAST(s.LAST_ACCESSED AS DATE)) AS DAYS_SINCE_ACCESS, COUNT(a.ACCESS_ID) AS ACCESS_COUNT_100D FROM SENSOR_READING s
LEFT JOIN DATA_ACCESS_LOG a ON s.READING_ID = a.READING_ID AND a.ACCESS_TIMESTAMP >= SYSTIMESTAMP - INTERVAL '100' DAY(3)
GROUP BY s.READING_ID, s.DATA_SIZE, s.LAST_ACCESSED),
storage_stats AS (SELECT used_mb / total_capacity_mb AS STORAGE_UTILISATION FROM (SELECT SUM(DATA_SIZE) / 1024 / 1024 AS used_mb FROM SENSOR_READING) u CROSS JOIN STORAGE_CONFIGURATION c),
metrics AS (SELECT a.*, ss.STORAGE_UTILISATION, a.ACCESS_COUNT_100D / 100 AS ACCESS_FREQUENCY FROM access_stats a CROSS JOIN storage_stats ss)
SELECT READING_ID, DATA_SIZE, LAST_ACCESSED, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ROUND(ACCESS_FREQUENCY, 4) AS ACCESS_FREQUENCY, ROUND(STORAGE_UTILISATION, 4) AS STORAGE_UTILISATION, ROUND((STORAGE_UTILISATION * LN(DAYS_SINCE_ACCESS + 1)) / (ACCESS_FREQUENCY + 0.01), 4) AS H_SCORE, CASE WHEN(STORAGE_UTILISATION * LN(DAYS_SINCE_ACCESS + 1)) / (ACCESS_FREQUENCY + 0.01) >= 250 THEN 'ARCHIVE' ELSE 'KEEP' END AS HYBRID_DECISION FROM metrics;

SELECT * FROM HYBRID_ARCHIVAL_ANALYSIS FETCH FIRST 20 ROWS ONLY;

SELECT DAYS_SINCE_ACCESS, COUNT(*) AS RECORD_COUNT FROM HYBRID_ARCHIVAL_ANALYSIS
GROUP BY DAYS_SINCE_ACCESS
ORDER BY DAYS_SINCE_ACCESS DESC;

SELECT * FROM (SELECT DAYS_SINCE_ACCESS, COUNT(*) AS RECORD_COUNT, SUM(COUNT(*)) OVER (ORDER BY DAYS_SINCE_ACCESS DESC) AS CUMULATIVE_ARCHIVED FROM HYBRID_ARCHIVAL_ANALYSIS
GROUP BY DAYS_SINCE_ACCESS) WHERE CUMULATIVE_ARCHIVED >= 18302
ORDER BY DAYS_SINCE_ACCESS DESC
FETCH FIRST 5 ROWS ONLY;

SELECT CASE WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS >= 230 THEN 'BOTH_ARCHIVE' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS < 230 THEN 'BOTH_KEEP' WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS < 230 THEN 'HYBRID_ONLY' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS >= 230 THEN 'TIME_BASED_ONLY' END AS COMPARISON_GROUP,
COUNT(*) AS RECORD_COUNT FROM HYBRID_ARCHIVAL_ANALYSIS
GROUP BY CASE WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS >= 230 THEN 'BOTH_ARCHIVE' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS < 230 THEN 'BOTH_KEEP' WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS < 230 THEN 'HYBRID_ONLY' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS >= 230 THEN 'TIME_BASED_ONLY' END
ORDER BY COMPARISON_GROUP;

SELECT CASE WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS >= 230 THEN 'BOTH_ARCHIVE' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS < 230 THEN 'BOTH_KEEP' WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS < 230 THEN 'HYBRID_ONLY' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS >= 230 THEN 'TIME_BASED_ONLY' END AS COMPARISON_GROUP,
COUNT(*) AS RECORD_COUNT, ROUND(AVG(DAYS_SINCE_ACCESS), 2) AS AVG_DAYS_SINCE_ACCESS, ROUND(AVG(ACCESS_FREQUENCY), 4) AS AVG_ACCESS_FREQUENCY, ROUND(AVG(DATA_SIZE), 2) AS AVG_DATA_SIZE, ROUND(SUM(DATA_SIZE) / 1024 / 1024, 2) AS TOTAL_STORAGE_MB FROM HYBRID_ARCHIVAL_ANALYSIS
GROUP BY CASE WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS >= 230 THEN 'BOTH_ARCHIVE' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS < 230 THEN 'BOTH_KEEP' WHEN HYBRID_DECISION = 'ARCHIVE' AND DAYS_SINCE_ACCESS < 230 THEN 'HYBRID_ONLY' WHEN HYBRID_DECISION = 'KEEP' AND DAYS_SINCE_ACCESS >= 230 THEN 'TIME_BASED_ONLY' END
ORDER BY COMPARISON_GROUP;

WITH total_records AS (SELECT COUNT(*) AS TOTAL_COUNT FROM SENSOR_READING), hybrid_results AS (SELECT COUNT(*) AS ARCHIVED_RECORDS, SUM(DATA_SIZE) AS ARCHIVED_SIZE FROM HYBRID_ARCHIVAL_ANALYSIS WHERE HYBRID_DECISION = 'ARCHIVE'), time_results AS (SELECT COUNT(*) AS ARCHIVED_RECORDS, SUM(DATA_SIZE) AS ARCHIVED_SIZE FROM HYBRID_ARCHIVAL_ANALYSIS WHERE DAYS_SINCE_ACCESS >= 230)
SELECT 'HYBRID' AS STRATEGY, h.ARCHIVED_RECORDS, ROUND(h.ARCHIVED_SIZE / 1024 / 1024, 4) AS ARCHIVED_STORAGE_MB, ROUND(100 * h.ARCHIVED_RECORDS / t.TOTAL_COUNT, 2) AS PERCENT_RECORDS_ARCHIVED FROM hybrid_results h
CROSS JOIN total_records t
UNION ALL SELECT 'TIME_BASED' AS STRATEGY, r.ARCHIVED_RECORDS, ROUND(r.ARCHIVED_SIZE / 1024 / 1024, 4) AS ARCHIVED_STORAGE_MB, ROUND(100 * r.ARCHIVED_RECORDS / t.TOTAL_COUNT, 2) AS PERCENT_RECORDS_ARCHIVED FROM time_results r
CROSS JOIN total_records t;

SELECT READING_ID, DATA_SIZE, ROUND((DATA_SIZE / 1024) / (SELECT TOTAL_CAPACITY_MB FROM STORAGE_CONFIGURATION), 6) AS RECORD_STORAGE_UTILISATION, DAYS_SINCE_ACCESS,ACCESS_COUNT_100D, ACCESS_FREQUENCY, ROUND((((DATA_SIZE / 1024) / (SELECT TOTAL_CAPACITY_MB FROM STORAGE_CONFIGURATION))* LN(DAYS_SINCE_ACCESS + 1)) / (ACCESS_FREQUENCY + 0.01), 4) AS NEW_H_SCORE FROM HYBRID_ARCHIVAL_ANALYSIS
ORDER BY NEW_H_SCORE DESC
FETCH FIRST 20 ROWS ONLY;

SELECT CASE WHEN NEW_H_SCORE < 0.5 THEN '0-0.5' WHEN NEW_H_SCORE < 1 THEN '0.5-1' WHEN NEW_H_SCORE < 2 THEN '1-2' WHEN NEW_H_SCORE < 3 THEN '2-3' WHEN NEW_H_SCORE < 4 THEN '3-4' WHEN NEW_H_SCORE < 5 THEN '4-5' WHEN NEW_H_SCORE < 6 THEN '5-6' ELSE '6+' END AS SCORE_RANGE, COUNT(*) AS RECORD_COUNT FROM (
SELECT(((DATA_SIZE / 1024) /(SELECT TOTAL_CAPACITY_MB FROM STORAGE_CONFIGURATION)) * LN(DAYS_SINCE_ACCESS + 1)) / (ACCESS_FREQUENCY + 0.01) AS NEW_H_SCORE FROM HYBRID_ARCHIVAL_ANALYSIS)
GROUP BY CASE WHEN NEW_H_SCORE < 0.5 THEN '0-0.5' WHEN NEW_H_SCORE < 1 THEN '0.5-1' WHEN NEW_H_SCORE < 2 THEN '1-2' WHEN NEW_H_SCORE < 3 THEN '2-3'WHEN NEW_H_SCORE < 4 THEN '3-4' WHEN NEW_H_SCORE < 5 THEN '4-5' WHEN NEW_H_SCORE < 6 THEN '5-6' ELSE '6+' END
ORDER BY MIN(CASE WHEN NEW_H_SCORE < 0.5 THEN 0 WHEN NEW_H_SCORE < 1 THEN 0.5 WHEN NEW_H_SCORE < 2 THEN 1 WHEN NEW_H_SCORE < 3 THEN 2 WHEN NEW_H_SCORE < 4 THEN 3 WHEN NEW_H_SCORE < 5 THEN 4 WHEN NEW_H_SCORE < 6 THEN 5 ELSE 6 END);

SELECT COUNT(*) AS TOTAL_COLD_RECORDS FROM HYBRID_ARCHIVAL_ANALYSIS
WHERE ACCESS_COUNT_100D = 0;

SELECT 'HYBRID' AS STRATEGY, COUNT(*) AS COLD_RECORDS_ARCHIVED, ROUND(100 * COUNT(*) / 18418, 4) AS COLD_CAPTURE_RATE FROM HYBRID_ARCHIVAL_ANALYSIS WHERE HYBRID_DECISION = 'ARCHIVE' AND ACCESS_COUNT_100D = 0
UNION ALL
SELECT 'TIME_BASED' AS STRATEGY, COUNT(*) AS COLD_RECORDS_ARCHIVED, ROUND(100 * COUNT(*) / 18418, 4) AS COLD_CAPTURE_RATE FROM HYBRID_ARCHIVAL_ANALYSIS WHERE DAYS_SINCE_ACCESS >= 230 AND ACCESS_COUNT_100D = 0;

SELECT 'OLD_HYBRID' AS STRATEGY, COUNT(*) AS ACTIVE_RECORDS_ARCHIVED FROM HYBRID_ARCHIVAL_ANALYSIS WHERE HYBRID_DECISION = 'ARCHIVE' AND ACCESS_COUNT_100D > 0
UNION ALL
SELECT 'TIME_BASED' AS STRATEGY, COUNT(*) AS ACTIVE_RECORDS_ARCHIVED FROM HYBRID_ARCHIVAL_ANALYSIS WHERE DAYS_SINCE_ACCESS >= 230 AND ACCESS_COUNT_100D > 0;

CREATE OR REPLACE VIEW HYBRID_ARCHIVAL_NEW AS WITH access_stats AS (SELECT s.READING_ID, s.DATA_SIZE, s.LAST_ACCESSED, TRUNC(SYSDATE - CAST(s.LAST_ACCESSED AS DATE)) AS DAYS_SINCE_ACCESS, COUNT(a.ACCESS_ID) AS ACCESS_COUNT_100D FROM SENSOR_READING s LEFT JOIN DATA_ACCESS_LOG a ON s.READING_ID = a.READING_ID AND a.ACCESS_TIMESTAMP >= SYSTIMESTAMP - INTERVAL '100' DAY(3)
GROUP BY s.READING_ID, s.DATA_SIZE, s.LAST_ACCESSED), metrics AS (
SELECT READING_ID, DATA_SIZE, LAST_ACCESSED, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ACCESS_COUNT_100D / 100 AS ACCESS_FREQUENCY,(DATA_SIZE / 1024) / (SELECT TOTAL_CAPACITY_MB FROM STORAGE_CONFIGURATION) AS RECORD_STORAGE_UTILISATION FROM access_stats), scored AS (
SELECT m.*, (RECORD_STORAGE_UTILISATION * LN(DAYS_SINCE_ACCESS + 1)) / (ACCESS_FREQUENCY + 0.01) AS H_SCORE FROM metrics m)
SELECT READING_ID, DATA_SIZE, LAST_ACCESSED, DAYS_SINCE_ACCESS, ACCESS_COUNT_100D, ROUND(ACCESS_FREQUENCY, 4) AS ACCESS_FREQUENCY, ROUND(RECORD_STORAGE_UTILISATION, 6) AS RECORD_STORAGE_UTILISATION, ROUND(H_SCORE, 4) AS H_SCORE FROM scored;

SELECT H_SCORE, COUNT(*) AS RECORD_COUNT, SUM(COUNT(*)) OVER (ORDER BY H_SCORE DESC) AS CUMULATIVE_COUNT FROM HYBRID_ARCHIVAL_NEW
GROUP BY H_SCORE ORDER BY H_SCORE DESC
FETCH FIRST 30 ROWS ONLY;

SELECT H_SCORE AS THRESHOLD_CANDIDATE FROM (SELECT H_SCORE, ROW_NUMBER() OVER (ORDER BY H_SCORE DESC) AS RN FROM HYBRID_ARCHIVAL_NEW) WHERE RN = 18418;

SELECT COUNT(*) AS TOTAL_ARCHIVED, SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) AS COLD_ARCHIVED, SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS ACTIVE_ARCHIVED, ROUND(100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418, 4) AS COLD_CAPTURE_RATE FROM HYBRID_ARCHIVAL_NEW WHERE H_SCORE >= 2.4351;

SELECT threshold, total_archived, cold_archived, active_archived, ROUND(100 * cold_archived / 18418, 4) AS cold_capture_rate, ROUND(100 * (18418 - cold_archived) / 18418, 4) AS cold_miss_rate FROM (
SELECT threshold, SUM(CASE WHEN H_SCORE >= threshold THEN 1 ELSE 0 END) AS total_archived, SUM(CASE WHEN H_SCORE >= threshold AND ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) AS cold_archived, SUM(CASE WHEN H_SCORE >= threshold AND ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS active_archived FROM HYBRID_ARCHIVAL_NEW
CROSS JOIN (SELECT 0.5 AS threshold FROM DUAL UNION ALL SELECT 0.75 FROM DUAL UNION ALL SELECT 1 FROM DUAL UNION ALL SELECT 1.25 FROM DUAL UNION ALL SELECT 1.5 FROM DUAL UNION ALL SELECT 1.75 FROM DUAL UNION ALL SELECT 2 FROM DUAL UNION ALL SELECT 2.25 FROM DUAL UNION ALL SELECT 2.5 FROM DUAL UNION ALL SELECT 2.75 FROM DUAL UNION ALL SELECT 3 FROM DUAL UNION ALL SELECT 3.25 FROM DUAL UNION ALL SELECT 3.5 FROM DUAL UNION ALL SELECT 4 FROM DUAL UNION ALL SELECT 4.5 FROM DUAL UNION ALL SELECT 5 FROM DUAL)
GROUP BY threshold)
ORDER BY threshold;

SELECT 'HYBRID' AS STRATEGY, COUNT(*) AS RECORDS_ARCHIVED, ROUND(SUM(DATA_SIZE) / 1024 / 1024, 4) AS STORAGE_ARCHIVED_MB FROM HYBRID_ARCHIVAL_NEW WHERE H_SCORE >= 2.5
UNION ALL
SELECT 'TIME_BASED' AS STRATEGY, COUNT(*) AS RECORDS_ARCHIVED, ROUND(SUM(DATA_SIZE) / 1024 / 1024, 4) AS STORAGE_ARCHIVED_MB FROM HYBRID_ARCHIVAL_NEW WHERE DAYS_SINCE_ACCESS >= 230;

SELECT ROUND(100 * (MAX(CASE WHEN STRATEGY = 'TIME_BASED' THEN STORAGE_ARCHIVED_MB END) - MAX(CASE WHEN STRATEGY = 'HYBRID' THEN STORAGE_ARCHIVED_MB END)) / MAX(CASE WHEN STRATEGY = 'TIME_BASED' THEN STORAGE_ARCHIVED_MB END), 4) AS STORAGE_REDUCTION_PERCENT FROM (
SELECT 'HYBRID' AS STRATEGY, SUM(DATA_SIZE) / 1024 / 1024 AS STORAGE_ARCHIVED_MB FROM HYBRID_ARCHIVAL_NEW WHERE H_SCORE >= 2.5
UNION ALL
SELECT 'TIME_BASED', SUM(DATA_SIZE) / 1024 / 1024 FROM HYBRID_ARCHIVAL_NEW WHERE DAYS_SINCE_ACCESS >= 230);

SELECT
    'TIME_BASED' AS STRATEGY,
    COUNT(*) AS TOTAL_ARCHIVED,
    SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) AS COLD_ARCHIVED,
    SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END) AS ACTIVE_ARCHIVED,
    ROUND(
        100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418,
        4
    ) AS COLD_CAPTURE_RATE
FROM HYBRID_ARCHIVAL_NEW
WHERE DAYS_SINCE_ACCESS >= 230

UNION ALL

SELECT 'HYBRID', COUNT(*), SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END), SUM(CASE WHEN ACCESS_COUNT_100D > 0 THEN 1 ELSE 0 END), ROUND(100 * SUM(CASE WHEN ACCESS_COUNT_100D = 0 THEN 1 ELSE 0 END) / 18418, 4) FROM HYBRID_ARCHIVAL_NEW WHERE H_SCORE >= 2.5;

SELECT ROUND(100 * (94.9940 - 88.0715) / 88.0715, 4) AS RELATIVE_IMPROVEMENT_PERCENT, ROUND(94.9940 - 88.0715, 4) AS PERCENTAGE_POINT_IMPROVEMENT FROM DUAL;

SELECT ROUND(100 * (2093 - 559) / 2093, 4) AS ACTIVE_ARCHIVAL_REDUCTION_PERCENT FROM DUAL;

SELECT MIN(H_SCORE) AS MIN_H_SCORE, MAX(H_SCORE) AS MAX_H_SCORE, AVG(H_SCORE) AS AVG_H_SCORE, MEDIAN(H_SCORE) AS MEDIAN_H_SCORE FROM HYBRID_ARCHIVAL_NEW;